describe('Past Date Field Validation - Future Date Submission', () => {
  beforeEach(() => {
    cy.visit('/form/submission');
  });

  it('should display error when submitting form with future date in past date field', () => {
    // Intercept the form submission API
    cy.intercept('POST', '/api/form/submit').as('formSubmit');

    // Fill in form with a future date
    cy.get('[data-testid="past-date-input"]').type('2090-10-20');
    cy.get('[data-testid="name-input"]').type('John Doe');
    cy.get('[data-testid="email-input"]').type('john@example.com');

    // Submit the form
    cy.get('[data-testid="submit-button"]').click();

    // Wait for the API call
    cy.wait('@formSubmit');

    // Verify error message is displayed
    cy.get('[data-testid="past-date-error"]').should('be.visible');
    cy.get('[data-testid="past-date-error"]').should('contain', 'Date must be in the past');

    // Verify form was not submitted successfully
    cy.get('[data-testid="success-message"]').should('not.exist');
    cy.get('[data-testid="form-container"]').should('be.visible');
  });

  it('should allow form submission when past date is provided', () => {
    // Intercept the form submission API
    cy.intercept('POST', '/api/form/submit').as('formSubmit');

    // Fill in form with a past date
    cy.get('[data-testid="past-date-input"]').type('2023-01-15');
    cy.get('[data-testid="name-input"]').type('Jane Doe');
    cy.get('[data-testid="email-input"]').type('jane@example.com');

    // Submit the form
    cy.get('[data-testid="submit-button"]').click();

    // Wait for the API call
    cy.wait('@formSubmit');

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Form submitted successfully');

    // Verify error message does not exist
    cy.get('[data-testid="past-date-error"]').should('not.exist');

    // Verify form is cleared or redirected
    cy.get('[data-testid="form-container"]').should('be.visible');
  });
});
